  function commanderArrivalNotice(result){const e=result?.commander_event;if(!e)return null;const faction=result.faction,delta=Number(e.diplomatic_delta)||0,details=[{text:`${e.commander_name}が指揮官予備役へ加わりました。`,className:'positive'}];if(delta)details.push({text:`${e.diplomatic_label||'外交関係'}：+${delta}`,className:'positive'});return{faction,title:e.title||'新任指揮官着任',speech:e.message||`${e.commander_name}が我が軍へ着任しました。`,details,sfx:delta>0?'status_up':null};}
  function foreignStatusStageNotice(result){
    const f=result?.foreign_effect;
    if(!result?.approved||!f||f.before_stage?.id===f.after_stage?.id)return null;
    const fullMajor=(f.after_stage?.id==='FULL')&&((result.faction==='PATRIOT'&&(f.country==='FRANCE'||f.country==='SPAIN'))||(result.faction==='BRITISH'&&f.country==='GERMAN_AUXILIARIES'));
    if(fullMajor)return null;
    const rank={WATCHING:0,SECRET:1,SUSTAINED:2,FULL:3},beforeRank=rank[f.before_stage?.id]??0,afterRank=rank[f.after_stage?.id]??0;
    const german=f.country==='GERMAN_AUXILIARIES';
    const favorable=result.faction==='PATRIOT'?afterRank>beforeRank:german?afterRank>beforeRank:afterRank<beforeRank;
    let speech='';
    if(result.faction==='PATRIOT'){
      if(f.after_stage?.id==='SECRET')speech=`朗報です、将軍。${f.country_label}との秘密援助が締結されましたぜ！`;
      else if(f.after_stage?.id==='SUSTAINED')speech=`朗報です、将軍。${f.country_label}からの継続援助が始まりますぜ！`;
      else if(f.after_stage?.id==='FULL')speech=`将軍、${f.country_label}がついに本格介入へ踏み切りましたぜ！`;
      else speech=`将軍、${f.country_label}との外交関係が${f.after_stage?.label}へ変化しました。`;
    }else if(german){
      if(f.after_stage?.id==='SECRET')speech='将軍、ドイツ諸侯との秘密交渉が成立しました。補助兵契約が具体化し始めます。';
      else if(f.after_stage?.id==='SUSTAINED')speech='将軍、ドイツ諸侯との交渉は継続派遣の段階へ進みました。';
      else if(f.after_stage?.id==='FULL')speech='将軍、ドイツ諸侯との本格派遣契約が成立しました。補助軍の大規模投入が可能となります。';
      else speech=`将軍、ドイツ諸侯との交渉段階が${f.after_stage?.label}へ変化しました。`;
    }else{
      speech=favorable?`将軍、${f.country_label}への外交工作が奏功し、独立派への支援を「${f.before_stage?.label}」から「${f.after_stage?.label}」へ後退させました。`:`将軍、${f.country_label}の独立派支援が「${f.before_stage?.label}」から「${f.after_stage?.label}」へ進展してしまいました。`;
    }
    const details=[{text:`外交段階：${f.before_stage?.label} → ${f.after_stage?.label}`,className:favorable?'positive':'negative'}];
    if(result.faction==='PATRIOT'&&f.country==='NETHERLANDS'){
      const supply=C.foreign_aid?.countries?.NETHERLANDS?.quarterly_supply?.[f.after_stage?.id];
      if(supply&&(Number(supply.FOOD)||Number(supply.MATERIALS)))details.push({text:`政治フェーズ閉会時の援助：食糧${Number(supply.FOOD)||0}／物資${Number(supply.MATERIALS)||0}を発送`,className:'positive'},{text:'実際の到着量は援助航路の制海状況による到着率で決まります。',className:'neutral'});
    }
    return{faction:result.faction,title:german?'ドイツ諸侯交渉・段階変化':`${f.country_label}外交・段階変化`,speech,details,sfx:favorable?'status_up':'status_down'};
  }
  function submit(id){const all=states(),faction=all.military.current_faction||'PATRIOT',resultBox=$('pv-result');try{const out=P.submitProposal(all.military,all.cities,faction,id,C);window.__phase2UI.setState(out.state);resultBox.className=`political-result ${out.result.approved?'approved':'rejected'}`;resultBox.textContent=`${out.result.proposal_name}：${out.result.approved?'可決':'否決'}`;window.__cityCommandUI.addLog?.(`${out.result.proposal_name}は${out.result.approved?'可決':'否決'}。${out.result.trust_change?` 外交成果により議会信任${signed(out.result.trust_change)}。`:''}`,'event','政治結果');render();modal.hidden=true;const notices=[proposalNotice(out.result),foreignStatusStageNotice(out.result),commanderArrivalNotice(out.result)].filter(Boolean);showNotices(notices,()=>{modal.hidden=false;render();});}catch(error){resultBox.className='political-result rejected';resultBox.textContent=`提出不可：${error.message}`;}}
  function battleSituation(report){const value=Number(report.battle_trust_change)||0,count=Number(report.battle_result_count)||0;if(!count)return{label:'大きな戦闘なし',color:'#d8dfdb'};if(value>=4)return{label:'大きく優勢',color:window.CITY_COMMAND_CONFIG.seven_color_palette[0].color};if(value>0)return{label:'優勢',color:window.CITY_COMMAND_CONFIG.seven_color_palette[1].color};if(value<=-4)return{label:'大きく劣勢',color:window.CITY_COMMAND_CONFIG.seven_color_palette[6].color};if(value<0)return{label:'劣勢',color:window.CITY_COMMAND_CONFIG.seven_color_palette[5].color};return{label:'互角',color:'#d8dfdb'};}
