  function openingNotice(faction,report){const battle=battleSituation(report),voteClass=report.state_votes_delta>0?'positive':report.state_votes_delta<0?'negative':'neutral',starClass=report.strategic_stars_delta>0?'positive':report.strategic_stars_delta<0?'negative':'neutral',trustBefore=trustLabelColor(report.trust_label_before),trustAfter=trustLabelColor(report.trust_label_after),voteText=report.state_votes_before===report.state_votes_after?`${report.state_votes_after}票`:`${report.state_votes_before}票 → ${report.state_votes_after}票`,neutralVotes=Number(report.state_votes_all?.NEUTRAL)||0,warBefore=warWillLabelColor(report.war_will_label_before),warAfter=warWillLabelColor(report.war_will_label_after);const details=[{html:`議会信任：<span style="color:${trustBefore};font-weight:900">${report.trust_label_before}</span> → <span style="color:${trustAfter};font-weight:900">${report.trust_label_after}</span>`,className:'neutral'},{html:`戦争意志：<span style="color:${warBefore};font-weight:900">${report.war_will_label_before}</span> → <span style="color:${warAfter};font-weight:900">${report.war_will_label_after}</span>`,className:'neutral'},{html:`直近戦況：<span style="color:${battle.color};font-weight:900">${battle.label}</span>`,className:'neutral'},{html:`戦略支配：★${report.strategic_stars_before} → ★${report.strategic_stars_after}`,className:starClass},{html:`獲得州票：<span class="${voteClass}">${voteText}</span>（中立 ${neutralVotes}票）`,className:'neutral'}];if(report.logistics_clear_bonus)details.splice(2,0,{html:'兵站情勢：3か月間、支配都市の食糧・物資枯渇なし。戦争意志は維持・強化されました。',className:'positive'});return{faction,title:'議会情勢報告',speech:faction==='PATRIOT'?'将軍、大陸会議の情勢が動いたようですぜ。詳しいところをご報告します。':'将軍、本国議会の情勢に変化がございました。詳細をご報告いたします。',details};}
  function crisisNotice(faction){return{faction,title:'終戦危機',speech:faction==='PATRIOT'?'将軍、このままでは大陸会議はイギリスへの降伏を受け入れてしまいます！':'将軍、このままでは本国議会は我が軍の撤退、植民地の独立を受け入れてしまいます！',details:[{text:'戦争意志：終戦不可避',className:'negative'},{text:'次回政治フェーズまでに戦争意志を回復させてください。',className:'negative'}]};}
  function openPhase(done){window.__commandPhaseBGM?.stop?.(true);const all=states();all.military.runtime_flow_phase='POLITICAL';const key=`${all.military.calendar.year}-${all.military.calendar.month}`;if(openingUiKey===key&&(!modal.hidden||!notice.hidden))return;if(typeof done==='function')phaseCloseDone=done;const out=P.openPoliticalPhase(all.military,all.cities,C),faction=out.state.current_faction||'PATRIOT',report=out.opening_report[faction],items=[openingNotice(faction,report)];openingUiKey=key;window.__phase2UI.setState(out.state);window.__politicalPhaseBGM?.play?.(true);syncIndicators();modal.hidden=true;if(P.indicatorSummary(out.state,faction,C).war_will_crisis)items.push(crisisNotice(faction));window.__cityCommandUI.addLog?.(`政治フェーズ開幕。議会信任 ${report.trust_label_before}→${report.trust_label_after}、直近戦況 ${battleSituation(report).label}、戦略支配★ ${report.strategic_stars_before}→${report.strategic_stars_after}、獲得州票 ${report.state_votes_before}→${report.state_votes_after}、戦争意志 ${report.war_will_label_before}→${report.war_will_label_after}。`,'event','議会情勢');if(out.events.some(event=>event.type==='STRATEGIC_VICTORY_CONFIRMED'))window.__cityCommandUI.addLog?.('議会が戦略的優勢を認め、戦争終結交渉の開始を決定しました。','result','勝利確定');showNotices(items,()=>{modal.hidden=false;render();});}
